1	//! Integrity-sidecar helpers split out from `main.rs` as part of R24.
2	//!
3	//! Scope:
4	//!   - `IntegrityOpts` bundle (the pair of read/write integrity flags)
5	//!   - `sidecar_path` — canonical `<file>.sha256` path
6	//!   - `hex_lower` — lowercase hex encoding of a byte slice
7	//!   - `sha256_hex_of_file` — hash a file's current on-disk bytes
8	//!   - `verify_integrity` + `maybe_verify_integrity` — the read-side check
9	//!
10	//! Deliberately stays free of `Cli`-coupling: `IntegrityOpts` has public
11	//! fields (no `from_cli` constructor here), so the root module constructs
12	//! instances wherever the CLI is parsed.
13	
14	use anyhow::{Context, Result, anyhow, bail};
15	use sha2::{Digest, Sha256};
16	use std::fs;
17	use std::path::{Path, PathBuf};
18	
19	/// Pair of integrity-sidecar-related global flags, bundled to shorten call
20	/// signatures for read/write paths.
21	#[derive(Clone, Copy)]
22	pub(crate) struct IntegrityOpts {
23	    pub(crate) write_sidecar: bool,
24	    pub(crate) verify_on_read: bool,
25	    /// When true, a sidecar-write failure becomes a hard error. When false
26	    /// (default), the failure is logged to stderr and the outer operation
27	    /// still succeeds — the primary TOML data has already been atomically
28	    /// persisted at that point.
29	    pub(crate) strict: bool,
30	}
31	
32	/// Return the canonical sidecar path for `file`: `<file>.sha256`.
33	pub(crate) fn sidecar_path(file: &Path) -> PathBuf {
34	    let mut s = file.as_os_str().to_os_string();
35	    s.push(".sha256");
36	    PathBuf::from(s)
37	}
38	
39	/// Lowercase hex encoding of a byte slice. Replaces the `{:x}` formatter for
40	/// digest outputs, which stopped implementing `LowerHex` in sha2 0.11.
41	pub(crate) fn hex_lower(bytes: &[u8]) -> String {
42	    use std::fmt::Write;
43	    let mut s = String::with_capacity(bytes.len() * 2);
44	    for b in bytes {
45	        let _ = write!(s, "{:02x}", b);
46	    }
47	    s
48	}
49	
50	/// Compute the SHA-256 hex digest of a file's current bytes.
51	pub(crate) fn sha256_hex_of_file(file: &Path) -> Result<String> {
52	    let bytes =
53	        fs::read(file).with_context(|| format!("reading {} for hashing", file.display()))?;
54	    Ok(hex_lower(&Sha256::digest(&bytes)))
55	}
56	
57	/// If `--verify-integrity` was set, verify the target against its sidecar.
58	/// Errors if the sidecar is missing or the digest disagrees.
59	pub(crate) fn maybe_verify_integrity(file: &Path, integrity: IntegrityOpts) -> Result<()> {
60	    if !integrity.verify_on_read {
61	        return Ok(());
62	    }
63	    verify_integrity(file)
64	}
65	
66	pub(crate) fn verify_integrity(file: &Path) -> Result<()> {
67	    let sidecar = sidecar_path(file);
68	    if !sidecar.exists() {
69	        bail!(
70	            "integrity check failed: sidecar {} is missing (expected `<hex>  <basename>` format — rewrite the file without --no-write-integrity to regenerate)",
71	            sidecar.display()
72	        );
73	    }
74	    let sidecar_text = fs::read_to_string(&sidecar)
75	        .with_context(|| format!("reading sidecar {}", sidecar.display()))?;
76	    let expected = sidecar_text.split_whitespace().next().ok_or_else(|| {
77	        anyhow!(
78	            "integrity sidecar {} is empty or malformed",
79	            sidecar.display()
80	        )
81	    })?;
82	    if expected.len() != 64 || !expected.chars().all(|c| c.is_ascii_hexdigit()) {
83	        bail!(
84	            "integrity sidecar {} does not contain a 64-hex-char digest (got `{}`)",
85	            sidecar.display(),
86	            expected
87	        );
88	    }
89	    let actual = sha256_hex_of_file(file)?;
90	    if !expected.eq_ignore_ascii_case(&actual) {
91	        bail!(
92	            "integrity check failed for {}: expected {}, actual {} (sidecar: {})",
93	            file.display(),
94	            expected,
95	            actual,
96	            sidecar.display()
97	        );
98	    }
99	    Ok(())
100	}
