256	enum BlocksOp {
257	    /// Verify one or more named shared-blocks are byte-identical across files.
258	    ///
259	    /// Each `<marker-name>` is scanned for the HTML-comment pair:
260	    ///   `<!-- SHARED-BLOCK:<marker-name> START -->` … `<!-- SHARED-BLOCK:<marker-name> END -->`
261	    /// The hash is taken over the byte-content strictly between the markers
262	    /// (each line joined by `\n`, matching `awk '{print}' | sha256sum`).
263	    Verify {
264	        /// Files to check.
265	        files: Vec<PathBuf>,
266	        /// Block name(s) to verify. If omitted, the union of block names
267	        /// present in the first listed file is used.
268	        #[arg(long = "block")]
269	        block: Vec<String>,
270	    },
271	}
