290	/// Translate a parsed `Cli` into the module-local `IntegrityOpts` bundle.
291	/// Kept next to the CLI definition (rather than in `integrity.rs`) so the
292	/// integrity module stays free of the clap-derived `Cli` type.
293	fn integrity_opts_from_cli(cli: &Cli) -> IntegrityOpts {
294	    IntegrityOpts {
295	        write_sidecar: !cli.no_write_integrity,
296	        verify_on_read: cli.verify_integrity,
297	        strict: cli.strict_integrity,
298	    }
299	}
