301	fn main() {
302	    if let Err(err) = run() {
303	        // R16: `{:#}` prints the full anyhow cause chain inline; combined with
304	        // `with_context(…"parsing {}", path)` in `read_toml`, toml's Display
305	        // impl then emits line:col + caret diagnostics for syntax errors.
306	        eprintln!("tomlctl: {:#}", err);
307	        std::process::exit(1);
308	    }
309	}
310	
311	fn run() -> Result<()> {
312	    let cli = Cli::parse();
313	    let allow_outside = cli.allow_outside;
314	    let integrity = integrity_opts_from_cli(&cli);
315	    match cli.cmd {
316	        Cmd::Parse { file } => {
317	            maybe_verify_integrity(&file, integrity)?;
318	            let doc = read_toml(&file)?;
319	            print_json(&toml_to_json(&doc))?;
320	        }
321	        Cmd::Get { file, path } => {
322	            maybe_verify_integrity(&file, integrity)?;
323	            let doc = read_toml(&file)?;
324	            let out = match path.as_deref() {
325	                None | Some("") => toml_to_json(&doc),
326	                Some(p) => toml_to_json(
327	                    navigate(&doc, p).ok_or_else(|| anyhow!("key path `{}` not found", p))?,
328	                ),
329	            };
330	            print_json(&out)?;
331	        }
332	        Cmd::Set {
333	            file,
334	            path,
335	            value,
336	            ty,
337	        } => {
338	            mutate_doc(&file, allow_outside, integrity, |doc| {
339	                let v = parse_scalar(&value, ty)?;
340	                set_at_path(doc, &path, v)
341	            })?;
342	            println!("{{\"ok\":true}}");
343	        }
344	        Cmd::SetJson { file, path, json } => {
345	            let json = read_json_arg(&json)?;
346	            mutate_doc(&file, allow_outside, integrity, |doc| {
347	                let parsed: JsonValue = serde_json::from_str(&json).context("parsing --json")?;
348	                let last_key = path.rsplit_once('.').map(|(_, k)| k).unwrap_or(path.as_str());
349	                let v = maybe_date_coerce(last_key, &parsed)?;
350	                set_at_path(doc, &path, v)
351	            })?;
352	            println!("{{\"ok\":true}}");
353	        }
354	        Cmd::Validate { file } => {
355	            maybe_verify_integrity(&file, integrity)?;
356	            read_toml(&file)?;
357	            println!("{{\"ok\":true}}");
358	        }
359	        Cmd::Items { op } => items_dispatch(op, allow_outside, integrity)?,
360	        Cmd::Blocks { op } => blocks_dispatch(op)?,
361	    }
362	    Ok(())
363	}
