365	fn items_dispatch(op: ItemsOp, allow_outside: bool, integrity: IntegrityOpts) -> Result<()> {
366	    match op {
367	        ItemsOp::List {
368	            file,
369	            status,
370	            category,
371	            newer_than,
372	            file_filter,
373	            count,
374	        } => {
375	            maybe_verify_integrity(&file, integrity)?;
376	            let doc = read_toml(&file)?;
377	            let newer_than_dt = match newer_than.as_deref() {
378	                Some(s) => Some(
379	                    s.parse::<toml::value::Datetime>()
380	                        .with_context(|| format!("--newer-than `{}` is not a valid ISO date", s))?,
381	                ),
382	                None => None,
383	            };
384	            let filters = ListFilters {
385	                status: status.as_deref(),
386	                category: category.as_deref(),
387	                newer_than: newer_than_dt.as_ref(),
388	                file_filter: file_filter.as_deref(),
389	            };
390	            let list = items_list(&doc, filters)?;
391	            if count {
392	                let mut obj = serde_json::Map::new();
393	                obj.insert("count".into(), JsonValue::from(list.len()));
394	                print_json(&JsonValue::Object(obj))?;
395	            } else {
396	                print_json(&JsonValue::Array(list))?;
397	            }
398	        }
399	        ItemsOp::Get { file, id } => {
400	            maybe_verify_integrity(&file, integrity)?;
401	            let doc = read_toml(&file)?;
402	            print_json(&items_get(&doc, &id)?)?;
403	        }
404	        ItemsOp::Add { file, json } => {
405	            let json = read_json_arg(&json)?;
406	            mutate_doc(&file, allow_outside, integrity, |doc| items_add(doc, &json))?;
407	            println!("{{\"ok\":true}}");
408	        }
409	        ItemsOp::Update {
410	            file,
411	            id,
412	            json,
413	            unset,
414	        } => {
415	            let json = read_json_arg(&json)?;
416	            mutate_doc(&file, allow_outside, integrity, |doc| {
417	                items_update(doc, &id, &json, &unset)
418	            })?;
419	            println!("{{\"ok\":true}}");
420	        }
421	        ItemsOp::Remove { file, id } => {
422	            mutate_doc(&file, allow_outside, integrity, |doc| items_remove(doc, &id))?;
423	            println!("{{\"ok\":true}}");
424	        }
425	        ItemsOp::Apply { file, ops, array, no_remove } => {
426	            let ops = read_json_arg(&ops)?;
427	            mutate_doc(&file, allow_outside, integrity, |doc| {
428	                items_apply_to_opts(doc, &ops, &array, no_remove)
429	            })?;
430	            println!("{{\"ok\":true}}");
431	        }
432	        ItemsOp::NextId { file, prefix } => {
433	            // R19: if the target ledger doesn't exist yet, there's nothing to
434	            // parse or verify — the "next" id is trivially `<prefix>1`. This
435	            // lets flows call `items next-id` before the ledger is initialised
436	            // (e.g. during bootstrap of a new flow directory).
437	            if !file.exists() {
438	                if prefix.is_empty() {
439	                    bail!("prefix must not be empty — use a letter like R, O, or A");
440	                }
441	                if prefix.chars().all(|c| c.is_ascii_digit()) {
442	                    bail!("prefix must not be all-digit — would collide with numeric-suffix parsing");
443	                }
444	                println!("{}", serde_json::to_string(&format!("{}1", prefix))?);
445	            } else {
446	                maybe_verify_integrity(&file, integrity)?;
447	                let doc = read_toml(&file)?;
448	                let id = items_next_id(&doc, &prefix)?;
449	                println!("{}", serde_json::to_string(&id)?);
450	            }
451	        }
452	        ItemsOp::FindDuplicates { file, tier } => {
453	            maybe_verify_integrity(&file, integrity)?;
454	            let doc = read_toml(&file)?;
455	            let groups = items_find_duplicates(&doc, tier)?;
456	            print_json(&JsonValue::Array(groups))?;
457	        }
458	        ItemsOp::Orphans { file } => {
459	            maybe_verify_integrity(&file, integrity)?;
460	            let doc = read_toml(&file)?;
461	            let orphans = items_orphans(&doc)?;
462	            print_json(&JsonValue::Array(orphans))?;
463	        }
464	    }
465	    Ok(())
466	}
