486	/// Run a closure that mutates a TOML document at `file` under the standard
487	/// write pipeline: `guard_write_path` → `with_exclusive_lock` → `read_toml` →
488	/// `f(&mut doc)` → `write_toml_with_sidecar`. Centralises what was previously
489	/// open-coded at each `Cmd::{Set,SetJson}` / `ItemsOp::{Add,Update,Remove,Apply}`
490	/// dispatch site.
491	fn mutate_doc<F>(
492	    file: &Path,
493	    allow_outside: bool,
494	    integrity: IntegrityOpts,
495	    f: F,
496	) -> Result<()>
497	where
498	    F: FnOnce(&mut TomlValue) -> Result<()>,
499	{
500	    guard_write_path(file, allow_outside)?;
501	    with_exclusive_lock(file, || {
502	        let mut doc = read_toml(file)?;
503	        f(&mut doc)?;
504	        // R3 TOCTOU narrowing: re-canonicalise target parent immediately before
505	        // the atomic persist and re-check that it still lies under `.claude/`.
506	        // Only enforced when `--allow-outside` was NOT set, since an explicit
507	        // opt-out was granted by the user in that case. This narrows (but does
508	        // not close) the window between `guard_write_path()` and `persist()`;
509	        // closing it fully requires O_NOFOLLOW via nix/rustix.
510	        if !allow_outside {
511	            recheck_claude_containment(file)?;
512	        }
513	        write_toml_with_sidecar(file, &doc, integrity)?;
514	        Ok(())
515	    })
516	}
517	
518	/// Re-canonicalise `file`'s parent and assert it still starts with the
519	/// `.claude/` canonical root. Used by `mutate_doc` to narrow the TOCTOU window
520	/// described in R3.
521	fn recheck_claude_containment(file: &Path) -> Result<()> {
522	    let parent = file
523	        .parent()
524	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
525	        .unwrap_or(Path::new("."));
526	    let parent_canonical = parent
527	        .canonicalize()
528	        .with_context(|| format!("re-canonicalising parent of {} before persist", file.display()))?;
529	    let root = repo_or_cwd_root()?;
530	    let claude_dir = root.join(".claude");
531	    let claude_canonical = claude_dir.canonicalize().unwrap_or(claude_dir);
532	    if parent_canonical.starts_with(&claude_canonical) {
533	        return Ok(());
534	    }
535	    bail!(
536	        "pre-persist containment check failed: target parent {} is no longer under {} (possible TOCTOU symlink swap since guard_write_path — aborting)",
537	        parent_canonical.display(),
538	        claude_canonical.display()
539	    )
540	}
