542	/// Acquire an exclusive sidecar `.lock` file around a write operation, with a
543	/// timeout so a stranded lock (crashed tomlctl, OS-mandatory Windows lock,
544	/// heavy contention) produces a clear error instead of hanging forever.
545	///
546	/// Timeout default is 30 seconds; override with the `TOMLCTL_LOCK_TIMEOUT`
547	/// env var (integer seconds). On the first observed contention the function
548	/// emits a one-shot stderr note so a human watching the terminal knows *why*
549	/// we're paused. The retry delay carries ±20% jitter (deterministic counter
550	/// hash, no external RNG) to avoid lockstep retries between competing
551	/// processes.
552	fn with_exclusive_lock<R>(path: &Path, f: impl FnOnce() -> Result<R>) -> Result<R> {
553	    use fs4::fs_std::FileExt;
554	    use std::time::Instant;
555	
556	    let lock_path = path.with_extension(match path.extension().and_then(|s| s.to_str()) {
557	        Some(ext) => format!("{}.lock", ext),
558	        None => "lock".to_string(),
559	    });
560	    let lock_file = std::fs::OpenOptions::new()
561	        .create(true)
562	        .truncate(false)
563	        .read(true)
564	        .write(true)
565	        .open(&lock_path)
566	        .with_context(|| format!("opening lock file {}", lock_path.display()))?;
567	
568	    // R25: effective timeout = env override if set, else DEFAULT_LOCK_TIMEOUT.
569	    // The error message reflects the effective timeout, not the constant default.
570	    let timeout = std::env::var("TOMLCTL_LOCK_TIMEOUT")
571	        .ok()
572	        .and_then(|s| s.parse::<u64>().ok())
573	        .map(std::time::Duration::from_secs)
574	        .unwrap_or(DEFAULT_LOCK_TIMEOUT);
575	    let base_delay_ms = LOCK_RETRY.as_millis() as u64;
576	    let start = Instant::now();
577	    let mut announced = false;
578	    let mut attempt: u64 = 0;
579	    loop {
580	        match lock_file.try_lock_exclusive() {
581	            Ok(true) => break,
582	            Ok(false) => {
583	                if !announced {
584	                    eprintln!(
585	                        "tomlctl: waiting for exclusive lock on {} …",
586	                        lock_path.display()
587	                    );
588	                    announced = true;
589	                }
590	                if start.elapsed() >= timeout {
591	                    bail!(
592	                        "lock held on {} for {} seconds — another tomlctl process may be hanging. If no tomlctl process is running, check for stale lock and delete {} manually.",
593	                        lock_path.display(),
594	                        timeout.as_secs(),
595	                        lock_path.display()
596	                    );
597	                }
598	                // ±20% jitter via a small counter hash (no RNG needed).
599	                // Hash maps attempt into [-20, 20] percent of base_delay_ms.

600	                let h = attempt
601	                    .wrapping_mul(0x9E37_79B9_7F4A_7C15)
602	                    .wrapping_add(0xD1B5_4A32_D192_ED03);
603	                let jitter_pct = (h % 41) as i64 - 20; // -20..=20
604	                let delta_ms = (base_delay_ms as i64) * jitter_pct / 100;
605	                let delay_ms = (base_delay_ms as i64 + delta_ms).max(1) as u64;
606	                std::thread::sleep(std::time::Duration::from_millis(delay_ms));
607	                attempt = attempt.wrapping_add(1);
608	            }
609	            Err(e) => {
610	                return Err(anyhow!(e)).with_context(|| {
611	                    format!("acquiring exclusive lock on {}", lock_path.display())
612	                });
613	            }
614	        }
615	    }
616	
617	    // R23: the lock_file binding is alive through this point; drop releases
618	    // the lock after `f()` returns. No explicit `let _ = lock_file;` needed.
619	    f()
620	}
