622	/// Refuse to write to files outside the current repo's `.claude/` directory
623	/// unless `--allow-outside` was passed on this invocation. Protects against
624	/// agent-influenced `artifacts.*` paths pointing at e.g. credential files.
625	///
626	/// Resolution strategy:
627	///   1. Canonicalise the target (parent if file doesn't exist yet).
628	///   2. Find the git top-level via `git rev-parse --show-toplevel`.
629	///      Fall back to CWD if git is missing or we're not inside a repo.
630	///   3. Assert canonical target lies under `<root>/.claude/`.
631	fn guard_write_path(file: &Path, allow_outside: bool) -> Result<()> {
632	    let canonical = canonicalize_for_write(file).with_context(|| {
633	        format!("canonicalising write target {}", file.display())
634	    })?;
635	
636	    let root = repo_or_cwd_root()?;
637	    let claude_dir = root.join(".claude");
638	    // Canonicalise the allowed root too so the prefix comparison is apples-to-apples
639	    // (on Windows, canonicalize yields extended-length `\\?\` paths).
640	    let claude_canonical = match claude_dir.canonicalize() {
641	        Ok(p) => p,
642	        Err(_) => claude_dir.clone(),
643	    };
644	
645	    if canonical.starts_with(&claude_canonical) {
646	        return Ok(());
647	    }
648	
649	    if allow_outside {
650	        eprintln!(
651	            "tomlctl: warning: writing outside .claude/ (path resolves to {}) — proceeding because --allow-outside was set",
652	            canonical.display()
653	        );
654	        return Ok(());
655	    }
656	
657	    bail!(
