663	/// Canonicalise a write target. If the file doesn't exist yet, canonicalise the
664	/// parent directory and re-attach the final component. Bails if neither the
665	/// file nor its parent directory exists.
666	///
667	/// R4: additionally rejects any `..` (`Component::ParentDir`) component in the
668	/// joined path. The parent canonicalises via `canonicalize()` which resolves
669	/// any embedded `..`, so a `ParentDir` in the joined result can only come from
670	/// the file-name component itself — a value like `../escape` is obviously
671	/// malicious and gets refused here even though it didn't appear after the
672	/// canonical parent prefix.
673	fn canonicalize_for_write(file: &Path) -> Result<PathBuf> {
674	    if let Ok(c) = file.canonicalize() {
675	        return Ok(c);
676	    }
677	    let parent = file
678	        .parent()
679	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
680	        .unwrap_or(Path::new("."));
681	    let parent_canonical = parent
682	        .canonicalize()
683	        .with_context(|| format!("parent directory {} not found", parent.display()))?;
684	    let name = file
685	        .file_name()
686	        .ok_or_else(|| anyhow!("write target `{}` has no file name", file.display()))?;
687	    let joined = parent_canonical.join(name);
688	    // Reject ParentDir / RootDir components past the canonical parent prefix.
689	    // Canonicalize() normalised the prefix, so anything in `joined.components()`
690	    // after the prefix that is a `..` came from the file-name piece — refuse.
691	    let prefix_len = parent_canonical.components().count();
692	    for comp in joined.components().skip(prefix_len) {
693	        match comp {
694	            std::path::Component::ParentDir | std::path::Component::RootDir => {
695	                bail!(
696	                    "write target `{}` contains a disallowed `..` or absolute root component after canonicalisation",
697	                    file.display()
698	                );
699	            }
700	            _ => {}
701	        }
702	    }
703	    Ok(joined)
704	}
