706	/// Return the containment anchor used by `guard_write_path`.
707	///
708	/// Resolution order:
709	///   1. `TOMLCTL_ROOT` env var, if set. Canonicalised; errors if the directory
710	///      does not exist. Intended for tests, chroots, and unusual layouts where
711	///      neither the git top-level nor the CWD is the right anchor.
712	///   2. `git rev-parse --show-toplevel` output, canonicalised.
713	///   3. Current working directory, canonicalised.
714	fn repo_or_cwd_root() -> Result<PathBuf> {
715	    if let Ok(env_root) = std::env::var("TOMLCTL_ROOT")
716	        && !env_root.is_empty()
717	    {
718	        let p = PathBuf::from(&env_root);
719	        return p.canonicalize().with_context(|| {
720	            format!("canonicalising TOMLCTL_ROOT={}", env_root)
721	        });
722	    }
723	    let cwd = std::env::current_dir().context("reading current working directory")?;
724	    match std::process::Command::new("git")
725	        .args(["rev-parse", "--show-toplevel"])
726	        .output()
727	    {
728	        Ok(out) if out.status.success() => {
729	            let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
730	            if s.is_empty() {
731	                Ok(cwd)
732	            } else {
733	                let p = PathBuf::from(s);
734	                Ok(p.canonicalize().unwrap_or(p))
735	            }
736	        }
737	        _ => Ok(cwd.canonicalize().unwrap_or(cwd)),
738	    }
739	}
