741	/// Write the TOML document and (unless suppressed) also write the `<file>.sha256`
742	/// sidecar.
743	///
744	/// R31 (torn-sidecar): the hash is computed in memory from the serialised
745	/// bytes BEFORE any rename, so both tempfiles (TOML + sidecar) are staged with
746	/// byte-content that is guaranteed consistent. We then `persist()` the TOML
747	/// first and the sidecar second, both under the existing `<file>.lock`
748	/// exclusive lock. A reader that interleaves between the two `persist()`
749	/// calls either:
750	///   (a) sees the OLD TOML + OLD sidecar — hashes agree, passes integrity;
751	///   (b) sees the NEW TOML + OLD sidecar — the OLD sidecar's hash is stale,
752	///       reader fails integrity; this matches the outcome readers would see
753	///       if a writer crashed after the first persist (desired behaviour);
754	///   (c) sees the NEW TOML + NEW sidecar — hashes agree, passes integrity.
755	/// The previous hash-after-rename pipeline had a window where a reader could
756	/// observe NEW bytes but computed the hash BEFORE the sidecar was refreshed;
757	/// that window is now closed.
758	///
759	/// Failure to persist the sidecar is reported as a stderr warning but does
760	/// not fail the outer write — the primary TOML is already durable. Set
761	/// `--strict-integrity` to upgrade that warning to a hard error.
762	fn write_toml_with_sidecar(
763	    path: &Path,
764	    value: &TomlValue,
765	    integrity: IntegrityOpts,
766	) -> Result<()> {
767	    let serialized = toml::to_string_pretty(value).context("serialising TOML")?;
768	    let bytes = serialized.as_bytes();
769	
770	    if !integrity.write_sidecar {
771	        return atomic_write(path, bytes);
772	    }
773	
774	    // Stage both tempfiles with hash computed from the same in-memory bytes.
775	    let hex = hex_lower(&Sha256::digest(bytes));
776	    let sidecar = sidecar_path(path);
777	    let basename = path
778	        .file_name()
779	        .ok_or_else(|| anyhow!("target `{}` has no file name", path.display()))?
780	        .to_string_lossy()
781	        .into_owned();
782	    let sidecar_contents = format!("{}  {}\n", hex, basename);
783	
784	    // Persist TOML first; if this fails, the sidecar never appeared on disk
785	    // at all. If it succeeds, we immediately persist the sidecar — under the
786	    // same exclusive lock there is no concurrent writer, and any reader
787	    // observing a mid-swap state lands on the consistent combinations
788	    // documented above.
789	    atomic_write(path, bytes)?;
790	    if let Err(e) = atomic_write(&sidecar, sidecar_contents.as_bytes()) {
791	        if integrity.strict {
792	            return Err(e).with_context(|| {
793	                format!(
794	                    "wrote {} but failed to refresh integrity sidecar (--strict-integrity was set, so this is a hard error)",
795	                    path.display()
796	                )
797	            });
798	        }
799	        eprintln!(
800	            "tomlctl: warning: wrote {} but failed to refresh integrity sidecar: {:#}",
801	            path.display(),
802	            e
803	        );
804	    }
805	    Ok(())
806	}
