809	/// Atomic-replace pattern: write `bytes` to a tempfile in the same directory as
810	/// `path`, `sync_all()` to flush to disk, then `persist()` to rename into place.
811	/// The `sync_all` call is load-bearing — without it, a crash between rename and
812	/// fsync can leave the target empty on some filesystems. See the tempfile crate
813	/// docs (`/stebalien/tempfile`) for the canonical pattern.
814	fn atomic_write(path: &Path, bytes: &[u8]) -> Result<()> {
815	    let parent = path
816	        .parent()
817	        .and_then(|p| if p.as_os_str().is_empty() { None } else { Some(p) })
818	        .unwrap_or(Path::new("."));
819	    let mut tmp = tempfile::NamedTempFile::new_in(parent)
820	        .with_context(|| format!("creating temp file in {}", parent.display()))?;
821	    tmp.as_file_mut()
822	        .write_all(bytes)
823	        .with_context(|| format!("writing temp file for {}", path.display()))?;
824	    tmp.as_file()
825	        .sync_all()
826	        .with_context(|| format!("fsync temp file for {}", path.display()))?;
827	    tmp.persist(path)
828	        .map_err(|e| anyhow!("atomic rename to {} failed: {}", path.display(), e.error))?;
829	    Ok(())
830	}
