899	fn infer_type(s: &str) -> ScalarType {
900	    if s == "true" || s == "false" {
901	        ScalarType::Bool
902	    } else if looks_like_date(s) {
903	        ScalarType::Date
904	    } else if s.parse::<i64>().is_ok() {
905	        ScalarType::Int
906	    } else {
907	        ScalarType::Str
