911	fn looks_like_date(s: &str) -> bool {
912	    let b = s.as_bytes();
913	    b.len() == 10
914	        && b[4] == b'-'
915	        && b[7] == b'-'
916	        && b[..4].iter().all(|c| c.is_ascii_digit())
917	        && b[5..7].iter().all(|c| c.is_ascii_digit())
918	        && b[8..10].iter().all(|c| c.is_ascii_digit())
919	}
