921	fn toml_to_json(v: &TomlValue) -> JsonValue {
922	    match v {
923	        TomlValue::String(s) => JsonValue::String(s.clone()),
924	        TomlValue::Integer(i) => JsonValue::from(*i),
925	        TomlValue::Float(f) => serde_json::Number::from_f64(*f)
926	            .map(JsonValue::Number)
927	            .unwrap_or(JsonValue::Null),
928	        TomlValue::Boolean(b) => JsonValue::Bool(*b),
929	        TomlValue::Datetime(dt) => JsonValue::String(dt.to_string()),
930	        TomlValue::Array(a) => JsonValue::Array(a.iter().map(toml_to_json).collect()),
931	        TomlValue::Table(t) => {
932	            let mut m = serde_json::Map::new();
933	            for (k, v) in t.iter() {
934	                m.insert(k.clone(), toml_to_json(v));
935	            }
936	            JsonValue::Object(m)
937	        }
938	    }
939	}
