941	fn json_to_toml(v: &JsonValue) -> Result<TomlValue> {
942	    match v {
943	        JsonValue::Null => bail!("TOML has no null type"),
944	        JsonValue::Bool(b) => Ok(TomlValue::Boolean(*b)),
945	        JsonValue::Number(n) => {
946	            if let Some(i) = n.as_i64() {
947	                Ok(TomlValue::Integer(i))
948	            } else if let Some(f) = n.as_f64() {
949	                Ok(TomlValue::Float(f))
950	            } else {
951	                bail!("number `{}` is not representable in TOML", n)
952	            }
953	        }
954	        JsonValue::String(s) => Ok(TomlValue::String(s.clone())),
955	        JsonValue::Array(a) => {
956	            let items: Result<Vec<_>> = a.iter().map(json_to_toml).collect();
957	            Ok(TomlValue::Array(items?))
958	        }
959	        JsonValue::Object(m) => {
960	            let mut t = toml::Table::new();
961	            for (k, v) in m.iter() {
962	                t.insert(k.clone(), json_to_toml(v)?);
963	            }
964	            Ok(TomlValue::Table(t))
965	        }
966	    }
967	}
