1004	/// Bundle of optional per-field filters for `items list`. All populated filters
1005	/// combine via logical AND; unset filters are no-ops.
1006	#[derive(Clone, Copy, Default)]
1007	struct ListFilters<'a> {
1008	    status: Option<&'a str>,
1009	    category: Option<&'a str>,
1010	    newer_than: Option<&'a toml::value::Datetime>,
1011	    file_filter: Option<&'a str>,
1012	}
