1014	fn items_list(doc: &TomlValue, filters: ListFilters<'_>) -> Result<Vec<JsonValue>> {
1015	    let items = items_array(doc, "items")?;
1016	    let mut out = Vec::new();
1017	    for item in items {
1018	        let Some(tbl) = item.as_table() else { continue };
1019	        if let Some(want) = filters.status
1020	            && str_field(tbl, "status") != want
1021	        {
1022	            continue;
1023	        }
1024	        if let Some(want) = filters.category
1025	            && str_field(tbl, "category") != want
1026	        {
1027	            continue;
1028	        }
1029	        if let Some(want) = filters.file_filter
1030	            && str_field(tbl, "file") != want
1031	        {
1032	            continue;
1033	        }
1034	        if let Some(threshold) = filters.newer_than {
1035	            let Some(ff) = tbl.get("first_flagged").and_then(|v| v.as_datetime()) else {
1036	                continue;
1037	            };
1038	            if !datetime_gt(ff, threshold) {
1039	                continue;
1040	            }
1041	        }
1042	        out.push(toml_to_json(item));
1043	    }
1044	    Ok(out)
1045	}
