1156	/// Extended variant of `items_apply_to` honouring the `--no-remove` flag (R37).
1157	/// When `no_remove` is true, the batch is scanned up-front for any `remove` op;
1158	/// if present, the whole apply is refused — no partial mutation occurs because
1159	/// the check runs before the mutation loop.
1160	fn items_apply_to_opts(
1161	    doc: &mut TomlValue,
1162	    ops_json: &str,
1163	    array_name: &str,
1164	    no_remove: bool,
1165	) -> Result<()> {
1166	    let ops: JsonValue = serde_json::from_str(ops_json).context("parsing --ops")?;
1167	    let arr = ops
1168	        .as_array()
1169	        .ok_or_else(|| anyhow!("--ops must be a JSON array"))?;
1170	    if no_remove {
1171	        for (i, op) in arr.iter().enumerate() {
1172	            if op.get("op").and_then(|v| v.as_str()) == Some("remove") {
1173	                bail!(
1174	                    "op[{}] is a remove op, but --no-remove was set; this flag is used by review-apply/optimise-apply to prevent agent-generated payloads from erasing audit history",
1175	                    i
1176	                );
1177	            }
1178	        }
1179	    }
1180	    for (i, op) in arr.iter().enumerate() {
1181	        apply_single_op(doc, op, array_name).with_context(|| format!("op[{}] failed", i))?;
1182	    }
1183	    Ok(())
1184	}
