1186	fn apply_single_op(doc: &mut TomlValue, op: &JsonValue, array_name: &str) -> Result<()> {
1187	    let obj = op
1188	        .as_object()
1189	        .ok_or_else(|| anyhow!("op must be a JSON object"))?;
