1197	                .get("json")
1198	                .ok_or_else(|| anyhow!("add op missing `json` field"))?;
1199	            items_add_value_to(doc, json, array_name)
1200	        }
1201	        "update" => {
1202	            let id = obj
1203	                .get("id")
1204	                .and_then(|v| v.as_str())
1205	                .ok_or_else(|| anyhow!("update op missing `id` field"))?;
1206	            let json = obj
1207	                .get("json")
1208	                .ok_or_else(|| anyhow!("update op missing `json` field"))?;
