1250	/// R36: return the JSON type-name discriminant for a `serde_json::Value`
1251	/// without echoing any user-supplied content. Used in error messages on
1252	/// apply-op parse failures, where the value could be an agent-generated
1253	/// `resolution` / `wontfix_rationale` string and would otherwise land on
1254	/// stderr verbatim.
1255	fn json_type_name(v: &JsonValue) -> &'static str {
1256	    match v {
1257	        JsonValue::Null => "null",
1258	        JsonValue::Bool(_) => "bool",
1259	        JsonValue::Number(_) => "number",
1260	        JsonValue::String(_) => "string",
1261	        JsonValue::Array(_) => "array",
1262	        JsonValue::Object(_) => "object",
1263	    }
1264	}
