1276	fn items_next_id(doc: &TomlValue, prefix: &str) -> Result<String> {
1277	    if prefix.is_empty() {
1278	        bail!("prefix must not be empty — use a letter like R, O, or A");
1279	    }
1280	    if prefix.chars().all(|c| c.is_ascii_digit()) {
1281	        bail!("prefix must not be all-digit — would collide with numeric-suffix parsing");
1282	    }
1283	    let mut max_n: u64 = 0;
1284	    if let Ok(arr) = items_array(doc, "items") {
1285	        for item in arr {
1286	            if let Some(id) = item_id(item)
1287	                && let Some(rest) = id.strip_prefix(prefix)
1288	                && let Ok(n) = rest.parse::<u64>()
1289	                && n > max_n
1290	            {
1291	                max_n = n;
1292	            }
1293	        }
1294	    }
1295	    Ok(format!("{}{}", prefix, max_n + 1))
1296	}
