1323	fn find_duplicates_tier_a(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1324	    // Group under two key-spaces:
1325	    //   by (file, symbol) when symbol is non-empty
1326	    //   by (file, summary) otherwise
1327	    // An item appears in exactly one group (either symbol-keyed or summary-keyed).
1328	    let mut by_symbol: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1329	    let mut by_summary: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1330	    for (i, item) in items.iter().enumerate() {
1331	        let Some(tbl) = item.as_table() else { continue };
1332	        let file = str_field(tbl, "file");
1333	        let symbol = str_field(tbl, "symbol");
1334	        if !symbol.is_empty() {
1335	            by_symbol
1336	                .entry((file.to_string(), symbol.to_string()))
1337	                .or_default()
1338	                .push(i);
1339	        } else {
1340	            let summary = str_field(tbl, "summary");
1341	            by_summary
1342	                .entry((file.to_string(), summary.to_string()))
1343	                .or_default()
1344	                .push(i);
1345	        }
1346	    }
1347	    let mut out = Vec::new();
1348	    for ((file, symbol), idxs) in &by_symbol {
1349	        if idxs.len() < 2 {
1350	            continue;
1351	        }
1352	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1353	        out.push(dup_group_json(
1354	            "A",
1355	            &format!("file={} symbol={}", file, symbol),
1356	            &refs,
1357	        ));
1358	    }
1359	    for ((file, summary), idxs) in &by_summary {
1360	        if idxs.len() < 2 {
1361	            continue;
1362	        }
1363	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1364	        out.push(dup_group_json(
1365	            "A",
1366	            &format!("file={} summary={}", file, summary),
1367	            &refs,
1368	        ));
1369	    }
1370	    Ok(out)
1371	}
