1373	fn find_duplicates_tier_b(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1374	    let mut groups: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
1375	    for (i, item) in items.iter().enumerate() {
1376	        let Some(tbl) = item.as_table() else { continue };
1377	        let file = str_field(tbl, "file");
1378	        let summary = str_field(tbl, "summary");
1379	        let severity = str_field(tbl, "severity");
1380	        let category = str_field(tbl, "category");
1381	        let symbol = str_field(tbl, "symbol");
1382	        let canonical = format!(
1383	            "{}|{}|{}|{}|{}",
1384	            file, summary, severity, category, symbol
1385	        );
1386	        let full = hex_lower(&Sha256::digest(canonical.as_bytes()));
1387	        let short = full[..16].to_string();
