1389	            .file_name()
1390	            .map(|s| s.to_string_lossy().into_owned())
1391	            .unwrap_or_else(|| file.to_string());
1392	        groups.entry((short, basename)).or_default().push(i);
1393	    }
1394	    let mut out = Vec::new();
1395	    for ((fingerprint, basename), idxs) in &groups {
1396	        if idxs.len() < 2 {
1397	            continue;
1398	        }
1399	        let refs: Vec<&TomlValue> = idxs.iter().map(|&i| &items[i]).collect();
1400	        out.push(dup_group_json(
1401	            "B",
1402	            &format!(
1403	                "suggestion fingerprint={} basename={}",
1404	                fingerprint, basename
1405	            ),
1406	            &refs,
1407	        ));
1408	    }
1409	    Ok(out)
1410	}
