1412	fn find_duplicates_tier_c(items: &[TomlValue]) -> Result<Vec<JsonValue>> {
1413	    // Candidates: items with empty/missing symbol AND line > 0.
1414	    #[derive(Clone)]
1415	    struct Candidate {
1416	        idx: usize,
1417	        file: String,
1418	        line: i64,
1419	    }
1420	    let mut by_file: HashMap<String, Vec<Candidate>> = HashMap::new();
1421	    for (i, item) in items.iter().enumerate() {
1422	        let Some(tbl) = item.as_table() else { continue };
1423	        let symbol = str_field(tbl, "symbol");
1424	        if !symbol.is_empty() {
1425	            continue;
1426	        }
1427	        let line = i64_field(tbl, "line");
1428	        if line <= 0 {
1429	            continue;
1430	        }
1431	        let file = str_field(tbl, "file").to_string();
1432	        by_file.entry(file.clone()).or_default().push(Candidate {
1433	            idx: i,
1434	            file,
1435	            line,
1436	        });
1437	    }
1438	
1439	    let mut out = Vec::new();
1440	    // Deterministic order: sort file keys.
1441	    let mut files: Vec<&String> = by_file.keys().collect();
1442	    files.sort();
1443	    for file in files {
1444	        let cands = &by_file[file];
1445	        // Sort by line then idx so sweep is deterministic.
1446	        // R26: `to_vec()` (clippy-preferred over `iter().cloned().collect()`)
1447	        // replaces the previous wholesale `cands.clone()` with the same
1448	        // semantics — we still need a mutable owned Vec for in-place sort,
1449	        // but without borrowing `by_file` mutably while iterating its keys.
1450	        let mut sorted: Vec<Candidate> = cands.to_vec();
1451	        sorted.sort_by(|a, b| a.line.cmp(&b.line).then(a.idx.cmp(&b.idx)));
1452	        let n = sorted.len();
1453	        let mut i = 0;
1454	        while i < n {
1455	            // Greedy: start a group at sorted[i], extend while every pair in
1456	            // the growing group satisfies |line_a - line_b| <= 10. Because
1457	            // items are sorted by line, the tightest constraint is between
1458	            // the group's min-line (sorted[i]) and the candidate's line.
1459	            let mut j = i + 1;
1460	            while j < n && sorted[j].line - sorted[i].line <= 10 {
1461	                j += 1;
1462	            }
1463	            if j - i >= 2 {
1464	                let refs: Vec<&TomlValue> = sorted[i..j].iter().map(|c| &items[c.idx]).collect();
1465	                out.push(dup_group_json(
1466	                    "C",
1467	                    &format!(
1468	                        "file={} line_window=[{}..{}]",
1469	                        sorted[i].file, sorted[i].line, sorted[j - 1].line
1470	                    ),
1471	                    &refs,
1472	                ));
1473	                i = j;
1474	            } else {
1475	                i += 1;
1476	            }
1477	        }
1478	    }
1479	    Ok(out)
1480	}
