1484	fn items_orphans(doc: &TomlValue) -> Result<Vec<JsonValue>> {
1485	    let items = match items_array(doc, "items") {
1486	        Ok(a) => a,
1487	        Err(_) => return Ok(Vec::new()),
1488	    };
1489	
1490	    // Build set of known IDs for dangling-dep check.
1491	    let mut known_ids: HashSet<String> = HashSet::new();
1492	    for item in items {
1493	        if let Some(id) = item_id(item) {
1494	            known_ids.insert(id.to_string());
1495	        }
1496	    }
1497	
1498	    let root = repo_or_cwd_root()?;
1499

1500	    let mut out = Vec::new();
1501	    for item in items {
1502	        let Some(tbl) = item.as_table() else { continue };
1503	        let id = str_field(tbl, "id");
1504	        let file = str_field(tbl, "file");
1505	        let symbol = str_field(tbl, "symbol");
1506	
1507	        // missing-file / symbol-missing classes (mutually exclusive: the first
1508	        // failing check wins).
1509	        if !file.is_empty() {
1510	            let resolved = resolve_relative_to_root(&root, file);
1511	            // R38: a RELATIVE ledger-item `file` field that escapes the root
1512	            // via `..` (e.g. `../../etc/passwd`) turns `fs::read_to_string`
1513	            // into an existence/symbol-presence oracle on arbitrary host
1514	            // paths. Canonicalise and assert containment for relative inputs
1515	            // only — absolute inputs are treated as intentional opt-in by
1516	            // the ledger author (this matches the pre-R38 behaviour on the
1517	            // happy path).
1518	            let is_relative = !Path::new(file).is_absolute();
1519	            let contained = if is_relative {
1520	                match (resolved.canonicalize().ok(), root.canonicalize().ok()) {
1521	                    (Some(c), Some(r)) => c.starts_with(&r),
1522	                    (Some(c), None) => c.starts_with(&root),
1523	                    (None, _) => true, // missing target falls through to `missing-file`.
1524	                }
1525	            } else {
1526	                true
1527	            };
1528	            if !contained {
1529	                let mut obj = serde_json::Map::new();
1530	                obj.insert("id".into(), JsonValue::String(id.into()));
1531	                obj.insert("class".into(), JsonValue::String("outside-repo".into()));
1532	                obj.insert("file".into(), JsonValue::String(file.into()));
1533	                out.push(JsonValue::Object(obj));
1534	            } else if !resolved.exists() {
1535	                let mut obj = serde_json::Map::new();
1536	                obj.insert("id".into(), JsonValue::String(id.into()));
1537	                obj.insert("class".into(), JsonValue::String("missing-file".into()));
1538	                obj.insert("file".into(), JsonValue::String(file.into()));
1539	                out.push(JsonValue::Object(obj));
1540	            } else if !symbol.is_empty() {
1541	                // R27: explicit match — IO errors surface as an `io-error`
1542	                // orphan instead of silently treating the file as empty
1543	                // (which would fire `symbol-missing` spuriously for
1544	                // unreadable-but-existing files).
1545	                match fs::read_to_string(&resolved) {
1546	                    Ok(contents) => {
1547	                        if !contents.contains(symbol) {
1548	                            let mut obj = serde_json::Map::new();
1549	                            obj.insert("id".into(), JsonValue::String(id.into()));
1550	                            obj.insert("class".into(), JsonValue::String("symbol-missing".into()));
1551	                            obj.insert("file".into(), JsonValue::String(file.into()));
1552	                            obj.insert("symbol".into(), JsonValue::String(symbol.into()));
1553	                            out.push(JsonValue::Object(obj));
1554	                        }
1555	                    }
1556	                    Err(_) => {
1557	                        let mut obj = serde_json::Map::new();
1558	                        obj.insert("id".into(), JsonValue::String(id.into()));
1559	                        obj.insert("class".into(), JsonValue::String("io-error".into()));
1560	                        obj.insert("file".into(), JsonValue::String(file.into()));
1561	                        out.push(JsonValue::Object(obj));
1562	                    }
1563	                }
1564	            }
1565	        }
1566	
1567	        // dangling-dep class (independent of the file/symbol axis; an item can
1568	        // be orphaned in both ways and will surface twice).
1569	        if let Some(deps) = tbl.get("depends_on").and_then(|v| v.as_array()) {
1570	            let mut missing: Vec<String> = Vec::new();
1571	            for dep in deps {
1572	                if let Some(d) = dep.as_str()
1573	                    && !known_ids.contains(d)
1574	                {
1575	                    missing.push(d.to_string());
1576	                }
1577	            }
1578	            if !missing.is_empty() {
1579	                let mut obj = serde_json::Map::new();
1580	                obj.insert("id".into(), JsonValue::String(id.into()));
1581	                obj.insert("class".into(), JsonValue::String("dangling-dep".into()));
1582	                obj.insert(
1583	                    "dangling_deps".into(),
1584	                    JsonValue::Array(missing.into_iter().map(JsonValue::String).collect()),
1585	                );
1586	                out.push(JsonValue::Object(obj));
1587	            }
1588	        }
1589	    }
1590	    Ok(out)
1591	}
