1600	#[derive(Debug)]
1601	struct BlocksReport {
1602	    ok: bool,
1603	    /// R28: the rendered JSON payload (top-level object containing `ok` +
1604	    /// `blocks`) that the dispatcher prints to stdout.
1605	    report: JsonValue,
1606	}
