1608	/// Extract the byte-content between `<!-- SHARED-BLOCK:NAME START -->` and
1609	/// `<!-- SHARED-BLOCK:NAME END -->` markers. Markers themselves are NOT
1610	/// included in the hash input. Inner lines are joined by `\n` (matching awk's
1611	/// default ORS), with every content line — including the last — followed by
1612	/// `\n`. Returns None if either marker is missing.
1613	fn extract_block(contents: &str, name: &str) -> Option<Vec<u8>> {
1614	    let start = format!("<!-- SHARED-BLOCK:{} START -->", name);
1615	    let end = format!("<!-- SHARED-BLOCK:{} END -->", name);
1616	    let mut in_block = false;
1617	    let mut saw_start = false;
1618	    let mut saw_end = false;
1619	    let mut out = Vec::new();
1620	    for line in contents.split('\n') {
1621	        if line == start {
1622	            in_block = true;
1623	            saw_start = true;
1624	            continue;
1625	        }
1626	        if line == end {
1627	            in_block = false;
1628	            saw_end = true;
1629	            continue;
1630	        }
1631	        if in_block {
1632	            out.extend_from_slice(line.as_bytes());
1633	            out.push(b'\n');
1634	        }
1635	    }
1636	    if saw_start && saw_end {
1637	        Some(out)
1638	    } else {
1639	        None
1640	    }
1641	}
