1643	fn scan_block_names(contents: &str) -> Vec<String> {
1644	    let mut names = Vec::new();
1645	    for line in contents.lines() {
1646	        let trimmed = line.trim();
1647	        if let Some(rest) = trimmed.strip_prefix("<!-- SHARED-BLOCK:")
1648	            && let Some(inner) = rest.strip_suffix(" START -->")
1649	        {
1650	            let n = inner.trim().to_string();
1651	            if !names.contains(&n) {
1652	                names.push(n);
1653	            }
1654	        }
1655	    }
1656	    names
1657	}
