1659	fn blocks_verify(files: &[PathBuf], blocks: &[String]) -> Result<BlocksReport> {
1660	    if files.is_empty() {
1661	        bail!("blocks verify: no files supplied");
1662	    }
1663	    // If no block names given, infer from the first file.
1664	    let effective_blocks: Vec<String> = if blocks.is_empty() {
1665	        let first = &files[0];
1666	        let c = fs::read_to_string(first)
1667	            .with_context(|| format!("reading {}", first.display()))?;
1668	        scan_block_names(&c)
1669	    } else {
1670	        blocks.to_vec()
1671	    };
1672	
1673	    // Preload every file once.
1674	    let mut contents_by_file: HashMap<PathBuf, String> = HashMap::new();
1675	    for f in files {
1676	        let c = fs::read_to_string(f)
1677	            .with_context(|| format!("reading {}", f.display()))?;
1678	        contents_by_file.insert(f.clone(), c);
1679	    }
1680	
1681	    let mut all_ok = true;
1682	    let mut blocks_out = Vec::new();
1683	    for name in &effective_blocks {
1684	        let mut per_file: Vec<(PathBuf, Option<String>)> = Vec::new();
1685	        for f in files {
1686	            let contents = &contents_by_file[f];
1687	            match extract_block(contents, name) {
1688	                Some(bytes) => {
1689	                    let digest = hex_lower(&Sha256::digest(&bytes));
1690	                    per_file.push((f.clone(), Some(digest)));
1691	                }
1692	                None => per_file.push((f.clone(), None)),
1693	            }
1694	        }
1695	
1696	        // R22: filter_map collapses the `is_some` filter and the later
1697	        // `.as_ref().unwrap()` calls into a single pass. `present` is now a
1698	        // Vec<(&PathBuf, &String)> — no Option unwraps below.
1699	        let mut present: Vec<(&PathBuf, &String)> = per_file
1700	            .iter()
1701	            .filter_map(|(p, h)| h.as_ref().map(|d| (p, d)))
1702	            .collect();
1703	        let missing: Vec<JsonValue> = per_file
1704	            .iter()
1705	            .filter(|(_, h)| h.is_none())
1706	            .map(|(f, _)| JsonValue::String(path_to_string(f)))
1707	            .collect();
1708	
1709	        let mut block_obj = serde_json::Map::new();
1710	        block_obj.insert("name".into(), JsonValue::String(name.clone()));
1711	
1712	        if present.is_empty() {
1713	            all_ok = false;
1714	            block_obj.insert("ok".into(), JsonValue::Bool(false));
1715	            block_obj.insert("missing".into(), JsonValue::Array(missing));
1716	            blocks_out.push(JsonValue::Object(block_obj));
1717	            continue;
1718	        }
1719	
1720	        // Sort present by file path for deterministic output.
1721	        present.sort_by(|a, b| a.0.cmp(b.0));
1722	        let first_hash = present[0].1.clone();
1723	        let drift = present.iter().any(|(_, h)| *h != &first_hash);
1724	
1725	        if drift || !missing.is_empty() {
1726	            all_ok = false;
1727	        }
1728	
1729	        if drift {
1730	            block_obj.insert("ok".into(), JsonValue::Bool(false));
1731	            let drift_arr: Vec<JsonValue> = present
1732	                .iter()
1733	                .map(|(f, h)| {
1734	                    let mut o = serde_json::Map::new();
1735	                    o.insert("file".into(), JsonValue::String(path_to_string(f)));
1736	                    o.insert("hash".into(), JsonValue::String((*h).clone()));
1737	                    JsonValue::Object(o)
1738	                })
1739	                .collect();
1740	            block_obj.insert("drift".into(), JsonValue::Array(drift_arr));
1741	            block_obj.insert("missing".into(), JsonValue::Array(missing));
1742	        } else {
1743	            let files_arr: Vec<JsonValue> = present
1744	                .iter()
1745	                .map(|(f, _)| JsonValue::String(path_to_string(f)))
1746	                .collect();
1747	            block_obj.insert("hash".into(), JsonValue::String(first_hash));
1748	            block_obj.insert("files".into(), JsonValue::Array(files_arr));
1749	            block_obj.insert("missing".into(), JsonValue::Array(missing));
1750	        }
1751	        blocks_out.push(JsonValue::Object(block_obj));
1752	    }
1753	
1754	    let mut top = serde_json::Map::new();
1755	    top.insert("ok".into(), JsonValue::Bool(all_ok));
1756	    top.insert("blocks".into(), JsonValue::Array(blocks_out));
1757	    Ok(BlocksReport {
1758	        ok: all_ok,
1759	        report: JsonValue::Object(top),
1760	    })
1761	}
