2081	        let mut doc = led();
2082	        items_add(
2083	            &mut doc,
2084	            r#"{"id":"R5","file":"src/c.rs","line":1,"severity":"suggestion","effort":"trivial","category":"quality","summary":"baz","first_flagged":"2026-04-17","rounds":1,"status":"open"}"#,
2085	        )
2086	        .unwrap();
2087	        write_toml_with_sidecar(&target, &doc, integrity_write_only()).unwrap();
2088	
2089	        // Sidecar exists with sha256sum-style format.
2090	        let sidecar = sidecar_path(&target);
2091	        assert!(sidecar.exists(), "sidecar must be written by default");
2092	        let side = fs::read_to_string(&sidecar).unwrap();
2093	        assert!(side.ends_with("  ledger.toml\n"), "got sidecar: {side:?}");
2094	        let hex = side.split_whitespace().next().unwrap();
2095	        assert_eq!(hex.len(), 64);
2096	
2097	        // Verify succeeds.
2098	        verify_integrity(&target).unwrap();
2099	
2100	        // Flip a byte in the target; verify now errors with both digests.
2101	        let mut bytes = fs::read(&target).unwrap();
2102	        // Mutate a byte in a way that keeps the file valid TOML — replace the
2103	        // first 'R' in the item ids with 'Q'. Actually we just need any change
2104	        // for the hash to differ; integrity check doesn't reparse.
2105	        let pos = bytes.iter().position(|&b| b == b'R').unwrap();
2106	        bytes[pos] = b'Q';
2107	        fs::write(&target, &bytes).unwrap();
2108	        let err = verify_integrity(&target).unwrap_err();
2109	        let msg = format!("{err:#}");
2110	        assert!(
2111	            msg.contains("expected") && msg.contains("actual"),
2112	            "expected dual-digest message, got: {msg}"
2113	        );
2114	    }
