2782	    #[test]
2783	    fn with_exclusive_lock_contention_times_out() {
2784	        use std::sync::mpsc;
2785	        use std::thread;
2786	        use std::time::{Duration, Instant};
2787	
2788	        let _guard = env_lock();
2789	        // Short timeout so the test finishes quickly.
2790	        unsafe {
2791	            std::env::set_var("TOMLCTL_LOCK_TIMEOUT", "1");
2792	        }
2793	
2794	        let dir = tempfile::tempdir().unwrap();
2795	        let target = dir.path().join("ledger.toml");
2796	        fs::write(&target, LEDGER).unwrap();
2797	
2798	        // Thread A takes the lock and sleeps long enough for thread B to
2799	        // hit its own timeout.
2800	        let (a_ready_tx, a_ready_rx) = mpsc::channel();
2801	        let (b_done_tx, b_done_rx) = mpsc::channel();
2802	        let target_a = target.clone();
2803	        let a = thread::spawn(move || {
2804	            with_exclusive_lock(&target_a, || {
2805	                a_ready_tx.send(()).unwrap();
2806	                // Hold the lock longer than B's timeout budget.
2807	                thread::sleep(Duration::from_millis(3_000));
2808	                Ok(())
2809	            })
2810	            .unwrap();
2811	        });
2812	        a_ready_rx.recv().unwrap();
2813	
2814	        let target_b = target.clone();
2815	        let b = thread::spawn(move || {
2816	            let started = Instant::now();
2817	            let res: Result<()> = with_exclusive_lock(&target_b, || Ok(()));
2818	            b_done_tx.send(started.elapsed()).unwrap();
2819	            res
2820	        });
2821	
2822	        let b_elapsed = b_done_rx.recv().unwrap();
2823	        let b_res = b.join().unwrap();
2824	        a.join().unwrap();
2825	
2826	        unsafe {
2827	            std::env::remove_var("TOMLCTL_LOCK_TIMEOUT");
2828	        }
2829	
2830	        assert!(b_res.is_err(), "thread B must time out under contention");
2831	        // With a 1-second timeout we should be done well under 3s (the hold).
2832	        assert!(
2833	            b_elapsed < Duration::from_millis(2_500),
2834	            "B took {:?}, expected < 2.5s under a 1s lock timeout",
2835	            b_elapsed
2836	        );
2837	    }
